-- Journeys build plan J10 — step 6, the demo: readiness, the page-map
-- confirmation, and the "how to test" frame line. Generated by `prisma migrate
-- diff`, then hand-extended with the one CHECK Prisma cannot express.
--
-- **Readiness is a browser's claim, recorded with who** (plan trap 1):
-- `Demo.readyAt` + `Demo.readyVerifiedById` say "this staff member's browser
-- received the reporter snippet's first report from the demo's own origin". The
-- server cannot see `postMessage` origins, so this is all it can honestly store.
-- `Build.pageMapConfirmedAt` is the developer's per-iteration confirmation of
-- the page map (journeys §7.5, the second banked trap).

-- AlterEnum
ALTER TYPE "DemoFrameLineKind" ADD VALUE 'HOW_TO_TEST';

-- AlterTable
ALTER TABLE "Demo" ADD COLUMN     "readyAt" TIMESTAMP(3),
ADD COLUMN     "readyVerifiedById" TEXT;

-- AlterTable
ALTER TABLE "Build" ADD COLUMN     "pageMapConfirmedAt" TIMESTAMP(3);

-- AddForeignKey
ALTER TABLE "Demo" ADD CONSTRAINT "Demo_readyVerifiedById_fkey" FOREIGN KEY ("readyVerifiedById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- Hand-written: readiness is a claim *by someone* — the time and the claimant
-- are both set or both null — and only a SITE demo has one (a mockup is served
-- by Root's own router, which injects the snippet itself; there is nothing to
-- prove). Written so that a NULL cannot slip through: each side tests IS NULL /
-- IS NOT NULL explicitly rather than comparing columns.
ALTER TABLE "Demo" ADD CONSTRAINT "Demo_ready_has_a_verifier" CHECK (
  ("readyAt" IS NULL AND "readyVerifiedById" IS NULL)
  OR ("readyAt" IS NOT NULL AND "readyVerifiedById" IS NOT NULL AND "kind" = 'SITE')
);
